(globalThis as any).window = { localStorage: { getItem: (k:string)=>store.get(k) ?? null, setItem: (k:string,v:string)=>store.set(k,v) } };
test('read', async () => {
  const { readStoredTheme, THEME_STORAGE_KEY } = await import('../theme');
  expect(readStoredTheme()).toBe('light');
  store.set(THEME_STORAGE_KEY,'dark'); expect(readStoredTheme()).toBe('dark');
  store.set(THEME_STORAGE_KEY,'system'); expect(readStoredTheme()).toBe('system');
  store.set(THEME_STORAGE_KEY,'garbage'); expect(readStoredTheme()).toBe('light');
  (globalThis as any).window = { get localStorage(){ throw new Error('denied'); } };
  expect(readStoredTheme()).toBe('light');
});
EOF
